/* @lc app=leetcode id=3277 lang=kotlin */ class Solution { fun maximumSubarrayXor(nums: IntArray, queries: Array<IntArray>): IntArray = nums.size.let { n -> Array(n) { IntArray(n) }.let { f -> Array(n) { IntArray(n) }.let { g -> (0 until n).forEach { i -> f[i].set(i, nums[i]).also { g[i][i] = nums[i] } }.let { (2..n).forEach { len -> (0..n - len).forEach { l -> (l + len - 1).let { r -> f[l].set(r, f[l][r - 1] xor f[l + 1][r]).also { g[l][r] = maxOf(f[l][r], g[l + 1][r], g[l][r - 1]) } } } } }.let { queries.map { (l, r) -> g[l][r] }.toIntArray() } } } } }